package mesh
import("strings";"sync";"time")
type Keepalive struct{NodeID string `json:"node_id"`;SentAt time.Time `json:"sent_at"`;Sequence uint64 `json:"sequence"`};type NodeState struct{NodeID string `json:"node_id"`;LastSeen time.Time `json:"last_seen"`;Healthy bool `json:"healthy"`;Sequence uint64 `json:"sequence"`};type StateStore struct{mu sync.RWMutex;nodes map[string]NodeState}
func NewStateStore()*StateStore{return &StateStore{nodes:make(map[string]NodeState)}}
func(s *StateStore)Observe(k Keepalive)NodeState{if s==nil{return NodeState{}};k.NodeID=strings.TrimSpace(k.NodeID);if k.NodeID==""||len(k.NodeID)>256{return NodeState{}};if k.SentAt.IsZero(){k.SentAt=time.Now().UTC()}else{k.SentAt=k.SentAt.UTC()};if k.SentAt.After(time.Now().UTC()){return NodeState{}};s.mu.Lock();defer s.mu.Unlock();if s.nodes==nil{s.nodes=make(map[string]NodeState)};if old,ok:=s.nodes[k.NodeID];ok&&k.Sequence<old.Sequence{return old};state:=NodeState{NodeID:k.NodeID,LastSeen:k.SentAt,Healthy:true,Sequence:k.Sequence};s.nodes[k.NodeID]=state;return state}
func(s *StateStore)Healthy(nodeID string,now time.Time,timeout time.Duration)bool{if s==nil||timeout<=0{return false};nodeID=strings.TrimSpace(nodeID);if nodeID==""{return false};if now.IsZero(){now=time.Now().UTC()}else{now=now.UTC()};s.mu.RLock();state,ok:=s.nodes[nodeID];s.mu.RUnlock();age:=now.Sub(state.LastSeen);return ok&&state.Healthy&&!state.LastSeen.IsZero()&&age>=0&&age<=timeout}
